<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><?php echo app('Illuminate\Foundation\Vite')(['resources/css/app.css','resources/js/app.js']); ?><title><?php echo e($office->name); ?> Queue Board<?php echo e($course ? ' — '.$course->name : ''); ?></title></head><body class="min-h-screen bg-slate-950 text-white p-6"><div class="max-w-6xl mx-auto"><div class="flex justify-between items-center mb-6"><div class="flex items-center gap-3"><div><div class="text-blue-400 text-sm font-bold uppercase tracking-widest">QueueFlow TMC</div><h1 class="text-3xl font-bold mt-1"><?php echo e($office->name); ?></h1><?php if($course): ?><div class="mt-2 inline-flex items-center gap-2 rounded-full bg-blue-950 border border-blue-800 px-3 py-1 text-xs font-bold text-blue-300"><?php echo e($course->code); ?> · <?php echo e($course->name); ?></div><?php endif; ?></div><span class="hidden sm:inline-flex items-center gap-2 rounded-full bg-slate-900 border border-slate-800 px-3 py-1.5 text-xs font-bold text-emerald-400"><span class="h-2 w-2 rounded-full bg-emerald-400 qf-live-dot"></span>LIVE</span></div><div class="text-slate-400 text-sm text-right"><?php echo e(now()->format('M d, Y h:i A')); ?></div></div><?php if($deployment): ?><div class="rounded-2xl bg-slate-900 border border-slate-800 p-4 mb-6"><div class="flex items-center justify-between gap-4 mb-3"><div class="flex items-center gap-3"><span class="rounded-full bg-blue-950 border border-blue-800 px-3 py-1 text-xs font-bold text-blue-300">Batch #<?php echo e($deployment->batch_no); ?></span><span class="text-sm text-slate-300 font-semibold"><?php echo e($slotsUsed); ?> / <?php echo e($slotsMax); ?> slots taken</span></div><span class="text-xs font-bold uppercase tracking-wide <?php echo e($slotsUsed < $slotsMax ? 'text-emerald-400' : 'text-amber-400'); ?>"><?php echo e($slotsUsed < $slotsMax ? 'Accepting tickets' : 'Batch is full'); ?></span></div><div class="h-2 rounded-full bg-slate-800 overflow-hidden"><div class="h-full rounded-full transition-all <?php echo e($slotsUsed < $slotsMax ? 'bg-emerald-400' : 'bg-amber-400'); ?>" style="width: <?php echo e(min(100, $slotsMax > 0 ? round($slotsUsed / $slotsMax * 100) : 0)); ?>%"></div></div></div><?php endif; ?><div class="grid lg:grid-cols-2 gap-6"><div class="qf-now-serving-card rounded-3xl bg-slate-900 border border-slate-800 p-10 text-center"><div class="text-slate-400 uppercase tracking-widest text-sm">Now Serving</div><div class="qf-flip-in qf-glow-num-strong text-7xl sm:text-8xl font-black text-blue-400 mt-5"><?php echo e($nowServing->queue_number ?? '—'); ?></div><div class="text-slate-400 mt-4">Please proceed to the service counter.</div></div><div class="rounded-3xl bg-slate-900 border border-slate-800 p-7"><div class="flex justify-between mb-5"><h2 class="font-bold text-xl">Waiting<?php echo e($course ? ' — '.$course->code : ''); ?></h2><span class="text-slate-400"><?php echo e($waiting->count()); ?></span></div><div class="space-y-2 qf-stagger"><?php $__empty_1 = true; $__currentLoopData = $waiting; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $ticket): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><div class="flex justify-between rounded-xl bg-slate-800 px-5 py-4"><span class="font-bold text-xl"><?php echo e($ticket->queue_number); ?></span><span class="text-slate-400"><?php echo e($ticket->created_at->format('h:i A')); ?></span></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="text-slate-500 text-center py-10"><?php echo e($course ? 'No one is waiting for this course.' : 'No one is waiting.'); ?></div><?php endif; ?></div></div></div></div><div class="flex justify-center mt-8"><a href="<?php echo e(route('dashboard')); ?>" class="inline-flex items-center gap-2 rounded-xl bg-slate-900 border border-slate-800 px-5 py-2.5 text-sm font-bold text-slate-200 hover:text-white hover:border-blue-600 hover:bg-blue-950 transition"><span aria-hidden="true">←</span> Back to Dashboard</a></div><script>setTimeout(()=>location.reload(),10000)</script></body></html><?php /**PATH C:\QUEUEFLOW TMC\QueueFlow_TMC\resources\views/queues/display.blade.php ENDPATH**/ ?>